import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.TickingAreasLoadStatus{Preload: true}
WAITING = bytes.fromhex("01")

# generated by gophertunnel b8bd735:
# packet.TickingAreasLoadStatus{Preload: false}
NOT_WAITING = bytes.fromhex("00")

GOLDENS = [
    pytest.param(v2225.TickingAreasLoadStatusPacket(waiting_for_preload=True), WAITING, id="waiting"),
    pytest.param(v2225.TickingAreasLoadStatusPacket(waiting_for_preload=False), NOT_WAITING, id="not-waiting"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_ticking_areas_load_status_is_packet_179(version):
    assert version.PACKETS[179] is version.TickingAreasLoadStatusPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_ticking_areas_load_status_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_ticking_areas_load_status_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_an_empty_ticking_areas_load_status_body_is_rejected():
    with pytest.raises(ValueError, match="at byte"):
        v2225.TickingAreasLoadStatusPacket.from_bytes(b"")
